import json
C="https://cdn.shopify.com/s/files/1/0596/8573/2467/files/"
P=[]
def add(handle,title,date,variants,imgs,desc):
    vs=[]
    for v in variants.split(';'):
        v=v.strip()
        if not v: continue
        vid,rest=v.split(':',1)
        opt,price,av=rest.rsplit(':',2)
        size=opt.split('/')[-1].strip() if '/' in opt else opt.strip()
        if size.upper() in ('NAVY','BLACK'): size=opt.split('/')[0].strip()
        vs.append([int(vid),size,int(price),av.strip()=='true'])
    P.append({"h":handle,"t":title,"d":date[:10],"v":vs,"i":[C+x for x in imgs],"s":desc})
